// Exact finite census for a fixed crossing count on the closed double torus.
// The atlas file is generated by atlas.py. All gluing shifts are traversed.
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <limits>
#include <numeric>
#include <sstream>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;
using Word = vector<int>;
using Weights = array<int, 6>;
using Sides = array<int, 12>;
struct Hit {
    int side, pos, rev;
};
struct Route {
    vector<Hit> hits;
    Weights visits{};
};
struct Shape {
    Sides mate{}, edge{};
    Weights rep{}, balance{};
    array<vector<int>, 2> circle;
    vector<Weights> autos;
    array<vector<Route>, 6> routes;
};
struct Relabel {
    int shape;
    Sides loc;
};
array<Shape, 6> shapes;
unordered_map<uint64_t, Relabel> relabels;
uint64_t encode(const Sides &p) {
    uint64_t key = 0;
    for (int v : p)
        key = (key << 4) | v;
    return key;
}
void atlas(const string &path) {
    ifstream in(path);
    int count = 0;
    if (!(in >> count) || count != 6)
        throw runtime_error("atlas missing");
    for (int i = 0; i < 6; ++i) {
        Shape &s = shapes[i];
        for (int &v : s.mate)
            in >> v;
        int k = 0;
        for (int d = 0; d < 12; ++d)
            if (d < s.mate[d]) {
                s.rep[k] = d;
                s.edge[d] = s.edge[s.mate[d]] = k++;
            }
        for (auto &c : s.circle) {
            int size;
            in >> size;
            c.resize(size);
            for (int &v : c)
                in >> v;
        }
        s.balance.fill(-1);
        for (int d : s.circle[0])
            ++s.balance[s.edge[d]];
        int a;
        in >> a;
        s.autos.resize(a);
        for (auto &perm : s.autos)
            for (int &v : perm)
                in >> v;
        for (int b = 1; b <= 5; ++b) {
            int m;
            in >> m;
            s.routes[b].resize(m);
            for (auto &r : s.routes[b]) {
                int len;
                in >> len;
                r.hits.resize(len);
                for (auto &h : r.hits) {
                    in >> h.side >> h.pos >> h.rev;
                    ++r.visits[s.edge[h.side]];
                }
            }
        }
        array<int, 4> order = {0, 1, 2, 3};
        do {
            for (int turns = 0; turns < 81; ++turns) {
                Sides lab, p;
                int v = turns;
                for (int t = 0; t < 4; ++t, v /= 3)
                    for (int j = 0; j < 3; ++j)
                        lab[3 * t + j] = 3 * order[t] + (v + j) % 3;
                for (int d = 0; d < 12; ++d)
                    p[lab[d]] = lab[s.mate[d]];
                relabels.emplace(encode(p), Relabel{i, lab});
            }
        } while (next_permutation(order.begin(), order.end()));
    }
    if (!in || relabels.size() != 4563)
        throw runtime_error("atlas verification failed");
}
int windingCost(const Weights &w, const Route &r) {
    return inner_product(w.begin(), w.end(), r.visits.begin(), 0);
}
bool shortCircuit(const Shape &s, const Weights &w, int threshold) {
    for (const Route &r : s.routes[1])
        if (windingCost(w, r) < threshold)
            return true;
    return false;
}
struct Chart {
    int shape = -1;
    Weights w{};
    array<Word, 12> strips;
    bool fullSupport() const {
        return find(w.begin(), w.end(), 0) == w.end();
    }
};
struct Scratch {
    Word pos, neg, next, par, index, face, tri;
    vector<unsigned char> seen;
    Chart chart;
    Word child;
    vector<pair<int, int>> points;
    vector<pair<int, int>> order;
};
// A value of zero means the ribbon cannot fill S₂. A value of -1 records a bigon.
int cut(const Word &x, Scratch &s) {
    int n = int(x.size());
    if (!n)
        return 0;
    s.pos.resize(n);
    s.neg.resize(n);
    s.next.resize(2 * n);
    for (int j = 0; j < n; ++j) {
        int a = x[j], f = 2 * j, b = (j ? f - 1 : 2 * n - 1);
        if (a < 0)
            swap(f, b);
        s.pos[abs(a) - 1] = f;
        s.neg[abs(a) - 1] = b;
    }
    for (int j = 0; j < n; ++j) {
        s.next[s.pos[j] ^ 1] = s.pos[j + 1 == n ? 0 : j + 1];
        s.next[s.neg[j] ^ 1] = s.neg[j ? j - 1 : n - 1];
    }
    s.seen.assign(2 * n, 0);
    s.par.assign(2 * n, -1);
    s.tri.clear();
    int faces = 0, fresh = 2 * n;
    bool monogon = false;
    for (int start = 0; start < 2 * n; ++start)
        if (!s.seen[start]) {
            ++faces;
            int d = s.next[start];
            s.seen[start] = 1;
            if (d == start) {
                monogon = true;
                continue;
            }
            if (s.next[d] == start) {
                s.seen[d] = 1;
                s.par[d] = start;
                s.par[start] = d;
                continue;
            }
            s.face.clear();
            s.face.push_back(start);
            while (d != start) {
                s.seen[d] = 1;
                s.face.push_back(d);
                d = s.next[d];
            }
            int head = start;
            for (int j = 1; j < int(s.face.size()) - 2; ++j) {
                s.tri.insert(s.tri.end(), {head, s.face[j], fresh});
                head = fresh + 1;
                fresh += 2;
            }
            s.tri.insert(s.tri.end(), {head, s.face[s.face.size() - 2], s.face.back()});
        }
    if (faces > n - 2)
        return 0;
    if (monogon)
        return -1;
    if (faces != n - 2 || s.tri.size() != 12)
        throw runtime_error("wrong ribbon genus");
    s.index.resize(fresh);
    for (int j = 0; j < 12; ++j)
        s.index[s.tri[j]] = j;
    Sides p;
    for (int i = 0; i < 12; ++i) {
        int d = s.tri[i], e = d ^ 1;
        if (d < 2 * n)
            while (s.par[e] >= 0)
                e = s.par[e] ^ 1;
        p[i] = s.index[e];
    }
    auto it = relabels.find(encode(p));
    if (it == relabels.end())
        throw runtime_error("unknown chart");
    const auto &r = it->second;
    s.chart.shape = r.shape;
    for (int i = 0; i < 12; ++i) {
        auto &strip = s.chart.strips[i];
        strip.clear();
        int d = s.tri[r.loc[i]];
        if (d < 2 * n) {
            for (;;) {
                strip.push_back(d);
                d = s.par[d ^ 1];
                if (d < 0)
                    break;
            }
        }
        s.chart.w[shapes[r.shape].edge[i]] = int(strip.size());
    }
    return 1;
}
void neighbor(const Chart &c, const Route &r, Word &out, vector<pair<int, int>> &points) {
    points.clear();
    for (auto h : r.hits)
        for (int d : c.strips[h.side]) {
            int label = int(points.size()) + 1;
            points.emplace_back((d / 2) * 8 + ((d & 1) ? h.rev : h.pos), (d & 1) ? -label : label);
        }
    sort(points.begin(), points.end());
    out.resize(points.size());
    for (size_t i = 0; i < out.size(); ++i)
        out[i] = points[i].second;
}
struct Engine {
    array<int, 8> lower = {0, 0, 0, 4, 12, 24, 48, 96};
    array<Scratch, 8> work;
    // Low intersections imply a short path by a previously established threshold.
    // If limited=true, failure to find a short path is inconclusive.
    bool within(const Word &w, int b, bool limited = false) {
        if (int(w.size()) < lower[b + 1])
            return true;
        Scratch &s = work[b];
        int status = cut(w, s);
        if (status < 0) {
            cerr << "filling bigon at budget " << b << " word";
            for (int x : w)
                cerr << " " << x;
            cerr << endl;
            throw runtime_error("bigon in recursive argument");
        }
        if (!status)
            return true;
        if (b == 2)
            return false;
        const Shape &shape = shapes[s.chart.shape];
        if (shortCircuit(shape, s.chart.w, lower[b]))
            return true;
        int bound = limited ? 1 : b - (s.chart.fullSupport() ? 2 : 1);
        const auto &routes = shape.routes[bound];
        s.order.clear();
        for (size_t i = 0; i < routes.size(); ++i)
            s.order.emplace_back(windingCost(s.chart.w, routes[i]), int(i));
        sort(s.order.begin(), s.order.end());
        for (const auto &entry : s.order) {
            // A peripheral move with the current word length is harmless; recursion consumes a
            // step.
            neighbor(s.chart, routes[entry.second], s.child, s.points);
            if (within(s.child, b - 1, limited))
                return true;
        }
        return false;
    }
};
struct Totals {
    uint64_t widths = 0, orbits = 0, shifts = 0, connected = 0, fill = 0, dual = 0, probed = 0,
             survivors = 0;
};
struct Generator {
    const Shape &s;
    int n;
    Word top, bottom, matching, sign;
    Generator(const Shape &sh, int N) : s(sh), n(N), matching(2 * N), sign(2 * N) {}
    void bundles(const Weights &w) {
        Weights first;
        int off = 0;
        for (int i = 0; i < 6; ++i) {
            first[i] = off;
            off += w[i];
        }
        auto boundary = [&](Word &out, const Word &darts) {
            out.clear();
            for (int d : darts) {
                int j = s.edge[d];
                for (int k = 0; k < w[j]; ++k)
                    out.push_back(d == s.rep[j] ? 2 * (first[j] + k)
                                                : 2 * (first[j] + w[j] - 1 - k) + 1);
            }
        };
        boundary(top, s.circle[0]);
        boundary(bottom, s.circle[1]);
        if (int(top.size()) != n || int(bottom.size()) != n)
            throw runtime_error("unbalanced widths");
        reverse(bottom.begin(), bottom.end());
        for (int j = 0; j < n; ++j)
            sign[top[j]] = j + 1;
    }
    bool glue(int shift, Word &w) {
        for (int j = 0, k = shift; j < n; ++j) {
            int a = top[j], b = bottom[k];
            matching[a] = b;
            matching[b] = a;
            sign[b] = -j - 1;
            if (++k == n)
                k = 0;
        }
        w.clear();
        int d = top[0];
        do {
            w.push_back(sign[d]);
            d = matching[d ^ 1];
        } while (d != top[0]);
        return int(w.size()) == n;
    }
};
Word inverseWord(const Word &w) {
    Word v(w.size());
    for (int i = 0; i < int(w.size()); ++i)
        v[abs(w[i]) - 1] = w[i] > 0 ? i + 1 : -i - 1;
    return v;
}
template <class F>
void compositions(const Word &ids, int k, int remaining, Weights &w, F &&callback) {
    if (k == int(ids.size())) {
        if (!remaining)
            callback();
        return;
    }
    if (k + 1 == int(ids.size())) {
        w[ids[k]] = remaining;
        callback();
        return;
    }
    for (int i = 0; i <= remaining; ++i) {
        w[ids[k]] = i;
        compositions(ids, k + 1, remaining - i, w, callback);
    }
}
void printWord(const Word &w) {
    for (size_t i = 0; i < w.size(); ++i)
        cout << (i ? "," : "") << w[i];
}
bool census(int n, int target, int cutoff, int onlyShape, int modulus, int residue, Engine &e,
            bool stopFirst) {
    Totals t;
    const auto start = chrono::steady_clock::now();
    bool found = false;
    for (int type = 0; type < 6; ++type) {
        if (onlyShape >= 0 && onlyShape != type)
            continue;
        const Shape &s = shapes[type];
        array<Word, 3> groups;
        for (int j = 0; j < 6; ++j)
            groups[s.balance[j] + 1].push_back(j);
        Weights w{};
        Generator build(s, n);
        Word word, reverseWord;
        Scratch geometry;
        uint64_t id = 0;
        auto inspect = [&]() {
            ++id;
            if (found && stopFirst)
                return;
            if (int(id % modulus) != residue)
                return;
            if (shortCircuit(s, w, cutoff))
                return;
            ++t.widths;
            for (const auto &perm : s.autos) {
                for (int j = 0; j < 6; ++j) {
                    if (w[j] < w[perm[j]])
                        break;
                    if (w[j] > w[perm[j]])
                        return;
                }
            }
            ++t.orbits;
            build.bundles(w);
            for (int shift = 0; shift < n; ++shift) {
                ++t.shifts;
                if (!build.glue(shift, word))
                    continue;
                ++t.connected;
                reverseWord = inverseWord(word);
                int status = cut(reverseWord, geometry);
                if (status <= 0)
                    continue;
                ++t.fill;
                if (shortCircuit(shapes[geometry.chart.shape], geometry.chart.w, cutoff))
                    continue;
                ++t.dual;
                if (e.within(reverseWord, target - 1, true) || e.within(word, target - 1, true))
                    continue;
                ++t.probed;
                if (e.within(word, target - 1))
                    continue;
                ++t.survivors;
                found = true;
                cout << "WITNESS " << target << " " << n << " chart " << type << " widths ";
                for (int x : w)
                    cout << x << ' ';
                cout << "shift " << shift << " word ";
                printWord(word);
                cout << endl;
                if (stopFirst)
                    return;
            }
        };
        for (int tside = 0; tside <= n / 2; ++tside) {
            if ((groups[0].empty() || groups[2].empty()) && tside > 0)
                break;
            if (groups[1].empty() && n != 2 * tside)
                continue;
            compositions(groups[0], 0, tside, w, [&]() {
                compositions(groups[2], 0, tside, w,
                             [&]() { compositions(groups[1], 0, n - 2 * tside, w, inspect); });
            });
            if (found && stopFirst)
                break;
        }
        if (found && stopFirst)
            break;
    }
    cout << "COUNT " << target << " " << n << " " << onlyShape << " " << modulus << " " << residue
         << " widths " << t.widths << " orbits " << t.orbits << " shifts " << t.shifts
         << " connected " << t.connected << " filling " << t.fill << " dual " << t.dual << " exact "
         << t.probed << " hits " << t.survivors << " seconds "
         << chrono::duration<double>(chrono::steady_clock::now() - start).count() << endl;
    return found;
}
int main(int argc, char **argv) {
    try {
        if (argc < 3)
            throw runtime_error("usage: program atlas.txt census|check ...");
        atlas(argv[1]);
        Engine e;
        string mode = argv[2];
        if (mode == "check") {
            if (argc != 4)
                throw runtime_error("expected check BUDGET and a signed permutation on stdin");
            int b = stoi(argv[3]);
            if (b < 2 || b > 6)
                throw runtime_error("expected budget 2..6");
            Word w;
            int x;
            while (cin >> x)
                w.push_back(x);
            vector<bool> present(w.size() + 1);
            for (int v : w) {
                if (v == 0 || v < -int(w.size()) || v > int(w.size()) || present[abs(v)])
                    throw runtime_error("not a signed permutation");
                present[abs(v)] = true;
            }
            cout << "within " << b << " " << e.within(w, b) << endl;
            return 0;
        }
        if (mode != "census" || argc < 7)
            throw runtime_error("census target first last m5 [shape modulus residue stop]");
        int d = stoi(argv[3]), first = stoi(argv[4]), last = stoi(argv[5]);
        e.lower[5] = stoi(argv[6]);
        int shape = argc > 7 ? stoi(argv[7]) : -1, mod = argc > 8 ? stoi(argv[8]) : 1,
            res = argc > 9 ? stoi(argv[9]) : 0;
        bool stop = argc > 10 ? stoi(argv[10]) != 0 : true;
        if (d < 4 || d > 6 || first < 1 || last < first || mod < 1 || res < 0 || res >= mod ||
            shape < -1 || shape >= 6)
            throw runtime_error("invalid census range or partition");
        for (int n = first; n <= last; ++n)
            if (census(n, d, e.lower[d - 1], shape, mod, res, e, stop) && stop)
                break;
    } catch (const exception &e) {
        cerr << "Error: " << e.what() << endl;
        return 1;
    }
}
